-- Caso completo confirmado por el propietario; únicamente contenido de la guía.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('saldo-favor-hermanos-reversion',$texto$Saldo a favor entre hermanos: aplicar, deshacer y volver a aplicar $100$texto$,'Cobranza',$texto$El tutor reporta $300; administración verifica que recibió $400, conserva $100 a favor y los aplica al adeudo del hermano. Incluye reversión individual y reaplicación, sin otro movimiento bancario.$texto$,$texto$Dos alumnos activos con inscripción vigente, mismo tutor responsable financiero con acceso familiar, mismo plantel e institución y moneda MXN. Cuenta bancaria activa compatible y administrador persistido autorizado para validar y revertir aplicaciones. Fechas dentro de inscripción/ciclo; sin becas, descuentos ni recargos en estos cargos de prueba. No ejecutar transferencias bancarias reales para un ensayo. Si el ejemplo ya está realizado, consultar la evidencia sin repetir capturas. Conservar aparte las deudas de ejercicios anteriores.$texto$,$texto$Alumno A: cargo $300.00; hermano B: cargo $100.00. Reporte familiar $300.00, recibido confirmado $400.00. Banco B + $400.00 una sola vez. Aplicar $100 al hermano deja ambos cargos en $0.00 y disponible $0.00; deshacer esa aplicación recupera deuda $100.00 y crédito $100.00; reaplicar deja ambos en $0.00. Aplicación, reversión y reaplicación no cambian el banco. El propietario confirmó el recorrido completo el 09/10/2026.$texto$,1,DATE '2026-10-09','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CONCEPTO_COBRO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','PAGO_LEER','PAGO_VALIDAR','PAGO_CANCELAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='saldo-favor-hermanos-reversion';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('saldo-favor-hermanos-reversion',1,$texto$Identificar hermanos, tutor y cuenta bancaria$texto$,$texto$Administración$texto$,$texto$Tutores, Inscripciones y Cuentas financieras$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Control escolar → Tutores, busca el tutor del ejercicio y abre Editar. Comprueba que ambos hijos estén vinculados, con responsabilidad financiera y permiso de ver finanzas vigentes, y que el tutor tenga cuenta familiar activa. Si ya están configurados, no cambies sus datos. 2. Entra a Operación escolar → Control escolar → Inscripciones y consulta las inscripciones de ambos hijos. Identifica matrícula, alumno, institución, plantel, moneda y fechas del ciclo; deben ser compatibles para compartir este saldo. 3. Entra a Administración → Finanzas → Cuentas financieras; busca la cuenta bancaria del plantel → Aplicar filtros. Anota su Saldo actual como B; por ejemplo, $5,000.00. No lo captures como saldo inicial ni registres otro movimiento. 4. Conserva estas referencias para seleccionar los dos cargos nuevos y comparar el banco. Usa una ventana privada u otro navegador para el tutor, sin reemplazar la sesión administrativa.$texto$,$texto$Dos hermanos del mismo tutor/plantel/moneda; cuenta con saldo B.$texto$,$texto$Responsabilidad financiera y cuenta identificadas.$texto$,$texto$Las otras deudas de pruebas anteriores permanecen fuera del ejercicio; no se liquidan por tener saldo a favor.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('saldo-favor-hermanos-reversion',2,$texto$Preparar un concepto sin ajustes$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Conceptos de cobro. Busca SF-TEST-20261009 → Aplicar filtros. Si ya existe el concepto de este ejemplo, consúltalo sin duplicarlo. 2. Para un ensayo nuevo pulsa Nuevo registro; selecciona institución y captura Código SF-TEST-20261009, Nombre Prueba de saldo a favor entre hermanos y Categoría Otro. 3. Captura Descripción Recibir 400, cubrir 300 y aplicar 100 al hermano. Marca Concepto activo y deja Permite beca, Permite descuento y Permite recargo desmarcados para comparar importes exactos. 4. Pulsa Crear concepto y comprueba código/nombre en el listado. Si reproduces el ejercicio con otras fechas o alumnos, utiliza un código de prueba distinto y no modifiques conceptos de cobro reales.$texto$,$texto$SF-TEST-20261009 será el concepto de los cargos de $300.00 y $100.00.$texto$,$texto$Concepto activo sin ajustes automáticos.$texto$,$texto$El saldo a favor no se crea como otro concepto: deriva del dinero recibido que aún no se ha aplicado.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('saldo-favor-hermanos-reversion',3,$texto$Crear las cuotas individuales de $300 y $100$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Nuevo registro. Selecciona institución, plantel, inscripción del Alumno A y concepto SF-TEST-20261009. Captura Importe individual 300.00 y moneda MXN. 2. Selecciona Una sola vez, Fecha límite de pago 20/10/2026, Estado Activa e Incluir en generación automática de cargos. En Configuración adicional verifica inicio 09/10/2026 y fin 20/10/2026 dentro de inscripción/ciclo. Adapta todas las fechas si ejecutas la guía después del vencimiento. 3. Revisa Así quedará la cuota → Crear cuota; comprueba alumno, importe y fechas en el modal y confirma. Vuelve a Cuotas por alumno → Nuevo registro y repite para la inscripción del hermano B con Importe individual 100.00 y las mismas condiciones. 4. Busca el concepto en el listado y comprueba las dos cuotas: una por alumno. Si son las cuotas del ensayo ya terminado, sólo consulta; no crees copias para volver a generar el mismo cobro.$texto$,$texto$Cuota única del Alumno A $300.00; cuota única del hermano B $100.00.$texto$,$texto$Dos configuraciones independientes, todavía sin ingreso bancario.$texto$,$texto$La fecha límite debe quedar dentro de la vigencia de la cuota y de la inscripción/ciclo. No usar otras cuotas de $100 de pruebas anteriores.$texto$,$texto$/admin/cuotas-alumno/nuevo$texto$),
('saldo-favor-hermanos-reversion',4,$texto$Generar únicamente los dos adeudos del ejercicio$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos → Generar automáticos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos. Selecciona institución/plantel y Generar hasta 09/10/2026, o la fecha de inicio válida que elegiste. 2. Pulsa Visualizar cuotas por aplicar → Desmarcar todos. Marca únicamente SF-TEST-20261009 del Alumno A por $300.00 y del hermano B por $100.00. Revisa becas/descuentos cero y total $400.00. 3. Pulsa Confirmar y generar adeudos seleccionados; revisa los dos alumnos en el modal y confirma. Después pulsa Volver a adeudos de alumnos. 4. En Adeudos de alumnos busca SF-TEST-20261009 → Con saldo pendiente → Aplicar filtros. Abre Ver de cada cargo y anota su número/matrícula: deben tener saldos $300.00 y $100.00. Si ya existen, no vuelvas a generar ni reemplazar cargos.$texto$,$texto$Dos cargos nuevos, saldo total $400.00; banco todavía B.$texto$,$texto$Adeudos identificados para reportar sólo el de $300.$texto$,$texto$Seleccionar otras cuotas genera otras deudas. El botón de regreso sólo navega y no cancela cargos.$texto$,$texto$/admin/cargos/generar$texto$),
('saldo-favor-hermanos-reversion',5,$texto$Reportar $300 con comprobante de $400 desde la familia$texto$,$texto$Tutor$texto$,$texto$Portal familiar → Tus pagos → Reportar transferencia$texto$,$texto$1. Desde el menú lateral administrativo deja tu sesión abierta; en otra ventana privada entra a /familias e inicia sesión como el tutor. Selecciona al Alumno A → Tus pagos → Reportar transferencia. 2. Selecciona únicamente su cargo SF-TEST-20261009 de $300.00, verificando matrícula y número del cargo. No agregues el de $100 del hermano. El total calculado y bloqueado debe ser $300.00. 3. Selecciona la cuenta bancaria identificada, fecha/hora actuales no futuras y Referencia TEST-SALDO-FAVOR-400. Adjunta un comprobante de ensayo claramente identificado por $400.00; en Observaciones escribe Se depositaron 400 para cubrir el cargo de 300; conservar 100 a favor. 4. Revisa cargos/cuenta/importe y pulsa Enviar transferencia a revisión → revisa el modal → Confirmar y enviar a revisión. En Tus pagos verifica el reporte En revisión por $300.00; todavía no se reconoce el excedente hasta que administración lo valide.$texto$,$texto$Reporte solicitado $300.00; comprobante indica $400.00.$texto$,$texto$Reporte pendiente, banco B y deudas $300.00/$100.00.$texto$,$texto$La familia no modifica el monto ni registra por sí sola un saldo a favor. No se necesita una transferencia real para ensayar con datos de prueba.$texto$,NULL),
('saldo-favor-hermanos-reversion',6,$texto$Validar el recibido real de $400 y reconocer $100 a favor$texto$,$texto$Administración y tutor$texto$,$texto$Pagos recibidos → Ver → Gestión$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos. Busca TEST-SALDO-FAVOR-400 → Aplicar filtros → Ver. En Comprobantes abre el archivo en otra pestaña y verifica el recibido de $400.00; conserva el folio del pago. 2. En el mismo detalle abre Gestión. Conserva la cuenta destino precargada y pulsa El importe recibido es mayor al reportado. Captura Importe realmente recibido 400.00 y Motivo obligatorio: Se recibieron 400 para cubrir el cargo de 300; conservar 100 a favor del tutor. 3. Pulsa Validar y publicar, revisa alumno, reportado $300.00, recibido $400.00, cuenta y saldo a favor estimado $100.00; prueba Cancelar primero, sin publicar. Repite y confirma la validación una sola vez. 4. En Distribución verifica aplicado $300.00, devuelto $0.00 y saldo a favor $100.00. En Cuentas financieras verifica B + $400.00. En la ventana familiar recarga Tus pagos; debajo del historial aparece Saldo a favor de tu familia con recibido $400.00, aplicado $300.00 y disponible $100.00. El hermano todavía debe $100.00.$texto$,$texto$El ensayo utilizó PAG-20261009-000023; los ejercicios nuevos generan su propio folio.$texto$,$texto$Cargo A liquidado; $100 a favor; banco recibe $400 una sola vez.$texto$,$texto$Si ya está validado, no repitas el pago. El importe reportado original y el motivo se conservan. El acceso de recuperación no puede autorizar movimientos.$texto$,$texto$/admin/catalogos/pagos$texto$),
('saldo-favor-hermanos-reversion',7,$texto$Aplicar los $100 al cargo del hermano$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Distribución → Saldo a favor$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca el folio del paso anterior → Aplicar filtros → Ver → Distribución → Gestionar saldo a favor e historial. Comprueba disponible $100.00. 2. En Buscar alumno o concepto da foco para ver las primeras diez opciones o escribe tres caracteres. Selecciona el cargo de $100.00 del hermano B y verifica alumno, concepto y número. En su tarjeta deja Importe a aplicar 100.00. 3. En Motivo obligatorio escribe Aplicar los 100 sobrantes del pago del Alumno A al cargo de su hermano, a solicitud del tutor. En Revisa antes de aplicar comprueba disponible $100.00, aplicación $100.00 y restante $0.00. 4. Pulsa Aplicar saldo a favor. En el modal revisa pago de origen, alumno/cargo, importe, total y motivo; pulsa Cancelar primero, sin guardar. Repite y pulsa Confirmar operación. No registres otra transferencia ni otro pago.$texto$,$texto$Disponible $100.00 → aplicación al hermano $100.00 → disponible $0.00.$texto$,$texto$Ambos cargos quedan liquidados usando el mismo pago.$texto$,$texto$Sólo se ofrecen cargos compatibles del mismo tutor, plantel y moneda, con responsabilidad financiera vigente y sin un pago pendiente de revisión.$texto$,$texto$/admin/catalogos/pagos$texto$),
('saldo-favor-hermanos-reversion',8,$texto$Comprobar la distribución familiar y el banco sin otro ingreso$texto$,$texto$Administración y tutor$texto$,$texto$Adeudos, Pagos recibidos, cuentas y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca SF-TEST-20261009 → Liquidado — saldo $0 → Aplicar filtros. Abre Ver de cada alumno y comprueba saldo $0.00: A recibió $300.00 y B recibió $100.00. 2. Entra a Administración → Finanzas → Pagos recibidos; busca el folio → Ver → Distribución. Comprueba aplicaciones netas $400.00 y disponible $0.00. Abre Gestionar saldo a favor e historial y verifica registro del hermano con importe, motivo y responsable. 3. Entra a Administración → Finanzas → Cuentas financieras; busca la cuenta → Aplicar filtros y confirma B + $400.00, no B + $500.00. No debe existir otro movimiento por aplicar el crédito. 4. En la ventana familiar entra a /familias → selecciona cada hijo → Tus pagos y recarga. Estos cargos no aparecen pendientes; el saldo a favor disponible queda $0.00. Si permanece una fila histórica con disponible cero, no representa crédito utilizable. Consulta el comprobante PDF en otra pestaña; deja fuera otras deudas anteriores.$texto$,$texto$Aplicado A $300.00 + B $100.00 = $400.00; disponible $0.00.$texto$,$texto$El propietario confirmó cargos liquidados, portal sin disponible y cuenta sin movimiento adicional.$texto$,$texto$Una fila histórica de un pago con disponible cero no es otra deuda ni otro pago; no repetir la operación para ocultarla.$texto$,$texto$/admin/catalogos/pagos$texto$),
('saldo-favor-hermanos-reversion',9,$texto$Deshacer sólo la aplicación de $100 sin devolver dinero$texto$,$texto$Administración y tutor$texto$,$texto$Saldo a favor → Historial de aplicaciones$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca el mismo folio → Ver → Distribución → Gestionar saldo a favor e historial. En Historial de aplicaciones selecciona Aplicaciones a adeudos → Aplicar filtros. El filtro sólo cambia la lista; no cancela operaciones. 2. Localiza la tarjeta del hermano B por $100.00. Pulsa Deshacer esta aplicación; se abre el motivo únicamente para ese registro. Captura Prueba de reversión de los 100 aplicados al hermano para recuperar el saldo a favor del tutor. 3. Pulsa Revertir aplicación; revisa en el modal pago de origen, hermano, importe $100.00 y motivo. Pulsa Cancelar primero y comprueba que no cambia nada; repite y pulsa Confirmar operación. Cada aplicación se revierte individualmente, no toda la lista filtrada. 4. En Adeudos de alumnos busca el cargo del hermano → Con saldo pendiente → Ver: vuelve a deber $100.00 y A sigue liquidado. En el portal familiar recarga Tus pagos: deuda $100.00 y saldo a favor $100.00. En Cuentas financieras conserva B + $400.00. En el historial selecciona Todas las operaciones → Aplicar filtros y consulta aplicación/reversión, autor y motivo.$texto$,$texto$Deshacer libera $100.00 al crédito familiar y restaura la deuda del hermano por $100.00.$texto$,$texto$El propietario confirmó deuda y saldo a favor recuperados, sin cambio bancario.$texto$,$texto$NO entrar a Ejecutar devolución, ni seleccionar devolución total/parcial: una devolución sí saca dinero de la cuenta. No se borra el historial ni se puede revertir otra vez la misma aplicación. Cargos cancelados o incluidos en convenio pueden bloquear la reversión.$texto$,$texto$/admin/catalogos/pagos$texto$),
('saldo-favor-hermanos-reversion',10,$texto$Reaplicar y cerrar la prueba conservando las tres operaciones$texto$,$texto$Administración y tutor$texto$,$texto$Saldo a favor, Adeudos, cuentas y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca el mismo folio → Ver → Distribución → Gestionar saldo a favor e historial. Verifica disponible $100.00 y selecciona otra vez el mismo cargo pendiente del hermano por $100.00. 2. Deja Importe a aplicar 100.00 y captura Motivo obligatorio: Reaplicar los 100 a favor al adeudo del hermano después de verificar la reversión. Revisa total $100.00 y restante $0.00 → Aplicar saldo a favor → revisa el modal → Confirmar operación. 3. En Historial de aplicaciones selecciona Todas las operaciones → Aplicar filtros. Comprueba aplicación inicial, reversión y nueva aplicación con sus motivos/responsables. Exportar Excel conserva el filtro seleccionado; Aplicaciones a adeudos y Reversiones de aplicaciones sólo limitan lo consultado. No sumes los tres importes como abonos positivos: la reversión resta la aplicación anterior. 4. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos y comprueba ambos cargos en saldo $0.00. En Cuentas financieras conserva B + $400.00. En /familias → cada hijo → Tus pagos, recarga y verifica estos cargos liquidados y disponible $0.00. Si el ensayo ya terminó, utiliza esta guía para consultar y no repitas la reaplicación.$texto$,$texto$Historial del crédito: aplicar $100.00 − revertir $100.00 + reaplicar $100.00 = aplicación neta $100.00 al hermano.$texto$,$texto$El propietario confirmó el cierre completo: ambos cargos liquidados, crédito disponible cero y banco sin cambios después del ingreso original.$texto$,$texto$La guía no elimina otras deudas ni autoriza aplicar saldo entre distintos tutores/planteles/monedas. No recrear los registros del ejemplo al consultar la documentación.$texto$,$texto$/admin/catalogos/pagos$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;
